// Maybe the sensitivity and perspective values can be written directly in Svelte so we don't have to use Custom Properties
export function perspectiveHover(node) {
  const computedStyle = getComputedStyle(node)
  const sensitivity = computedStyle.getPropertyValue('--sensitivity')
  const perspective = computedStyle.getPropertyValue('--perspective')
  const transition = computedStyle.getPropertyValue('transition')

  node.addEventListener('pointerout', leave)
  node.addEventListener('pointermove', move)

  function calculateRotationValues(event) {
    const boundingRect = node.getBoundingClientRect()
    const xCenter = boundingRect.left + boundingRect.width / 2
    const yCenter = boundingRect.top + boundingRect.height / 2
    const x = (event.clientX - xCenter) / boundingRect.width
    const y = (event.clientY - yCenter) / boundingRect.height

    // Calculation rotation values
    const rotateX = y * -sensitivity + 'deg'
    const rotateY = x * sensitivity + 'deg'

    return { rotateX, rotateY }
  }

  // This event begins abruptly.
  function move(event) {
    const { rotateX, rotateY } = calculateRotationValues(event)

    // Apply rotation values
    node.style.transition = `none`
    node.style.transform = `perspective(${perspective}) rotateX(${rotateX}) rotateY(${rotateY})`
  }

  function leave(event) {
    node.style.transition = transition
    node.style.transform = `perspective(${perspective}) rotateX(0) rotateY(0)`
  }

  return {
    destroy() {
      node.addEventListener('pointerout', leave)
      node.addEventListener('pointermove', move)
    },
  }
}
